command:
/*
 * Creates a random NPC using the NPC generator roll tables.
 * Copy the "NPC Generator" folder from the "MgT2e Base Tables"
 * compendium into your world, in order to edit your own copy
 * of the generator.
 *
 * Execute this macro when a spacecraft token is selected. New
 * NPCs are created and added to the ship as crew.
 */

let selected = canvas.tokens.controlled;
let shipToken = null;
if (selected) {
  shipToken = selected[0];
  if (shipToken.actor.type !== "spacecraft") {
    return;
  }
} else {
  return;
}
const shipActor = shipToken.document.actor;


let npcFolder = await Folder.create({
  "name": "NPC Crew for " + shipToken.name,
  "type": "Actor",
  "color": "#FF0000"
});

const crewMembers = [ "Captain", "Engineer", "Gunner" ];

for (let member of crewMembers) {

  let npcData = {
      "type": "npc",
      "img": `systems/mgt2e/icons/actors/pilot.svg`,
      "ownership": {
          default: 2
      },
      folder: npcFolder._id,
      "system": {
          "settings": {
              hideUntrained: true,
              lockCharacteristics: true
          },
          "meta": {
             career: member,
             background: ""
          },
          "sophont": {
              age: 20,
              homeworld: ""
          },
          "description": ""
      }
  }
  //await game.mgt2e.generateNpc(npcData, "NPC Generator_");
  await game.mgt2e.generateNpc(npcData);
  let items = null;
  if (npcData.system.meta.items) {
    items = npcData.system.meta.items;
    delete npcData.system.meta.items;
  }

  const npc = await Actor.implementation.create(npcData);

  // Add to ship
  shipActor.system.crewed.crew[npc._id] = {};
  shipActor.update({"system.crewed": shipActor.system.crewed});


  const itemList = [];
  if (items) {
    const pack = game.packs.get("mgt2e-core.mgt2e-core-items");
    const index = await pack.getIndex();
    for (const itemName of items) {
      const entry = index.find(i => i.name === itemName);
      const item = await pack.getDocument(entry._id);
      itemList.push(item.toObject());
    }
  }
  if (itemList) {
    npc.createEmbeddedDocuments("Item", itemList);
  }
}
